import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import "./scroll-bend.css";

/**
 * Scroll Bend —— 一条会被速度压弯的卡片带。
 *
 * 借自 React Bits Pro 的同名组件（a strip of images that bulges or pinches
 * with your scroll speed）的形态：卡片排成一条带子横在面前，滚轮推着带子
 * 走；走得越快，带子中间鼓得越高（反向滚就往下兜），停下时自己慢慢展平。
 *
 * 实现上只有两件事：
 *   1. 每帧把「速度」衰减回 0，带子的位移由速度积分出来；
 *   2. 每张卡按它离中心的横向距离 u ∈ [-1,1] 取一条抛物线 —— 中间 1-u²
 *      最大、两端为 0 —— 乘上速度算出鼓包，再按抛物线的斜率给一点旋转，
 *      于是整条带子看上去是被速度压出来的弧，而不是各自在跳。
 *
 * 拖动、左右方向键、滚轮都能推动它；键盘 Tab 到哪张卡，带子就把它带到
 * 眼前。prefers-reduced-motion 时不做形变，只保留平移。
 */

export interface ScrollBendItem {
  id: string;
  title: string;
  meta?: string;
  /** 卡面上的小标（分类、编号之类）。 */
  kicker?: string;
  /** 卡片的主题色相 0..360；不传就按 id 算一个稳定的。 */
  hue?: number;
  /** 有图就铺满整张卡当底，标题压在图上；不传就是纯色卡。 */
  image?: string;
}

interface ScrollBendProps {
  items: ScrollBendItem[];
  onSelect?: (item: ScrollBendItem) => void;
  className?: string;
  emptyLabel?: string;
}

const CARD_STEP = 196;
const CARD_WIDTH = 176;
/** 速度（px/秒）到鼓包高度（px）的换算。 */
const BEND_PER_SPEED = 0.16;
const MAX_BEND = 74;
/** 速度每秒衰减到原来的 e^-2.4 ≈ 9%。 */
const BEND_DAMPING = 2.4;

function hashHue(id: string) {
  let hash = 5381;
  for (let index = 0; index < id.length; index += 1) {
    hash = (hash * 33) ^ id.charCodeAt(index);
  }
  return (hash >>> 0) % 360;
}

export function ScrollBend({
  items,
  onSelect,
  className = "",
  emptyLabel = "这一条上还没有内容。",
}: ScrollBendProps) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const offsetRef = useRef(0);
  const targetRef = useRef(0);
  const velocityRef = useRef(0);
  const bendRef = useRef(0);
  const dragRef = useRef<{ x: number; offset: number } | null>(null);
  const [reduced, setReduced] = useState(false);

  const hues = useMemo(
    () => new Map(items.map((item) => [item.id, item.hue ?? hashHue(item.id)])),
    [items],
  );

  const maxOffset = Math.max(0, (items.length - 1) * CARD_STEP);

  const clamp = useCallback(
    (value: number) => Math.max(0, Math.min(maxOffset, value)),
    [maxOffset],
  );

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const apply = () => setReduced(query.matches);
    apply();
    query.addEventListener("change", apply);
    return () => query.removeEventListener("change", apply);
  }, []);

  const push = useCallback(
    (delta: number) => {
      targetRef.current = clamp(targetRef.current + delta);
      velocityRef.current += delta * 3.4;
    },
    [clamp],
  );

  const onWheel = useCallback(
    (event: React.WheelEvent<HTMLDivElement>) => {
      const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY)
        ? event.deltaX
        : event.deltaY;
      // 横向到头的方向继续滚，不把页面也带跑。
      event.stopPropagation();
      push(delta);
    },
    [push],
  );

  const onPointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    dragRef.current = { x: event.clientX, offset: targetRef.current };
    event.currentTarget.setPointerCapture(event.pointerId);
  }, []);

  const onPointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag) return;
    const next = clamp(drag.offset - (event.clientX - drag.x));
    velocityRef.current += (drag.offset - (event.clientX - drag.x) - targetRef.current) * 2;
    targetRef.current = next;
  }, [clamp]);

  const onPointerUp = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    dragRef.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  }, []);

  const onKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowRight") {
        event.preventDefault();
        push(CARD_STEP);
      } else if (event.key === "ArrowLeft") {
        event.preventDefault();
        push(-CARD_STEP);
      }
    },
    [push],
  );

  /** 键盘走到某张卡，带子把它带到眼前。 */
  const focusCard = useCallback(
    (index: number) => {
      const next = clamp(index * CARD_STEP);
      velocityRef.current += (next - targetRef.current) * 3;
      targetRef.current = next;
    },
    [clamp],
  );

  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    let raf = 0;
    let last = performance.now();

    const loop = (now: number) => {
      raf = window.requestAnimationFrame(loop);
      const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000));
      last = now;
      const rect = viewport.getBoundingClientRect();
      const halfW = Math.max(1, rect.width / 2);

      // 位移追着目标走，速度决定鼓包；松开手后两者都自己归位。
      offsetRef.current += (targetRef.current - offsetRef.current) * Math.min(1, dt * 9);
      velocityRef.current *= Math.exp(-BEND_DAMPING * dt);
      const speed = Math.max(-900, Math.min(900, velocityRef.current));
      const wantBend = Math.max(-MAX_BEND, Math.min(MAX_BEND, speed * BEND_PER_SPEED));
      bendRef.current += (wantBend - bendRef.current) * Math.min(1, dt * 10);

      const bend = reduced ? 0 : bendRef.current;
      const offset = offsetRef.current;

      for (let index = 0; index < cardRefs.current.length; index += 1) {
        const node = cardRefs.current[index];
        if (!node) continue;
        const center = index * CARD_STEP - offset + CARD_WIDTH / 2;
        const u = Math.max(-1.4, Math.min(1.4, (center - halfW) / halfW));
        const bell = 1 - Math.min(1, u * u);
        // 抛物线在中心最高、两边落回 0；斜率就是那一点的「弯度」。
        const lift = bend * bell;
        const slope = (bend * -2 * u) / Math.max(160, halfW * 0.9);
        const scale = 1 + Math.abs(bend) * 0.0009 * bell;
        node.style.transform = `translate3d(${(index * CARD_STEP - offset).toFixed(1)}px, ${lift.toFixed(1)}px, 0) rotate(${slope.toFixed(3)}rad) scale(${scale.toFixed(3)})`;
      }
      viewport.dataset.bending = Math.abs(bend) > 2 ? "" : undefined;
    };

    raf = window.requestAnimationFrame(loop);
    return () => window.cancelAnimationFrame(raf);
  }, [reduced]);

  if (!items.length) {
    return (
      <div className={`scroll-bend scroll-bend--empty ${className}`.trim()}>
        <p>{emptyLabel}</p>
      </div>
    );
  }

  return (
    <div
      ref={viewportRef}
      className={`scroll-bend ${className}`.trim()}
      role="list"
      aria-label="卡片条"
      tabIndex={0}
      onWheel={onWheel}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onKeyDown={onKeyDown}
    >
      <div className="scroll-bend__track">
        {items.map((item, index) => {
          const hue = hues.get(item.id) ?? 210;
          return (
            <button
              key={item.id}
              type="button"
              ref={(node) => {
                cardRefs.current[index] = node;
              }}
              className="scroll-bend__card"
              data-cover={item.image ? "" : undefined}
              style={{ ["--card-hue" as string]: String(hue) }}
              onClick={() => onSelect?.(item)}
              onFocus={() => focusCard(index)}
              aria-label={`${item.title}${item.meta ? `，${item.meta}` : ""}`}
            >
              {/* 有图的时候整张卡就是那张图（图里已经写好了标题），文字不再
                  叠一层，免得同一句话读两遍 —— 读屏走 aria-label。 */}
              {item.image ? (
                <img
                  className="scroll-bend__cover"
                  src={item.image}
                  alt=""
                  draggable={false}
                />
              ) : (
                <>
                  {item.kicker ? (
                    <span className="scroll-bend__kicker">{item.kicker}</span>
                  ) : null}
                  <span className="scroll-bend__title">{item.title}</span>
                  {item.meta ? (
                    <span className="scroll-bend__meta">{item.meta}</span>
                  ) : null}
                </>
              )}
              <span className="scroll-bend__edge" aria-hidden="true" />
            </button>
          );
        })}
      </div>
      <p className="scroll-bend__hint" aria-hidden="true">
        滚动压弯这条带子 · 拖动或方向键翻看
      </p>
    </div>
  );
}

export default ScrollBend;
