/**
 * 图形验证码：注册那一步要照着一张图敲四个字符。
 *
 * 不连服务器也能用 —— 这张图是本机画出来的（canvas），答案就在内存里，
 * 校验也只在这台设备上发生。它拦不住真要有心的人，拦的是「随手点一下」。
 * 图上的噪点用「按答案播种」的伪随机数画：同一串字符每次画出来一模一样，
 * 输入框里多敲一个字也不会让整张图跟着跳。
 */
import { useEffect, useRef } from "react";
import { RotateCcw } from "lucide-react";
import "./picture-code.css";

/** 4 和 5 的槽位是按这个尺寸排的，改这里要连 CSS 一起看。 */
const WIDTH = 148;
const HEIGHT = 48;
const MONO = '"IBM Plex Mono", Consolas, "Courier New", monospace';
/** 去掉了 0/O、1/I/L 这些照着念都会念错的一对一对。 */
const ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

export function makePictureCode(length = 4) {
  let code = "";
  for (let index = 0; index < length; index += 1) {
    code += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
  }
  return code;
}

/** 大小写不较真：图上写的是大写，键盘上敲成小写也算对。 */
export function matchesPictureCode(input: string, expected: string) {
  return input.trim().toUpperCase() === expected.toUpperCase();
}

function seedOf(text: string) {
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash = Math.imul(hash ^ text.charCodeAt(index), 16777619);
  }
  return hash >>> 0;
}

/** mulberry32：够用的伪随机，同一个种子给出同一张图。 */
function seededRandom(seed: number) {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function paint(canvas: HTMLCanvasElement, text: string) {
  const ratio = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = WIDTH * ratio;
  canvas.height = HEIGHT * ratio;
  const ctx = canvas.getContext("2d");
  if (!ctx || !text) return;
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  const random = seededRandom(seedOf(text));

  const wash = ctx.createLinearGradient(0, 0, WIDTH, HEIGHT);
  wash.addColorStop(0, "#f5f2fc");
  wash.addColorStop(1, "#e5dff2");
  ctx.fillStyle = wash;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // 几道弧线，别让字孤零零浮着。
  ctx.lineWidth = 1.2;
  for (let index = 0; index < 5; index += 1) {
    ctx.strokeStyle = `rgba(143, 127, 192, ${(0.14 + random() * 0.24).toFixed(3)})`;
    ctx.beginPath();
    ctx.moveTo(random() * WIDTH, random() * HEIGHT);
    ctx.bezierCurveTo(
      random() * WIDTH,
      random() * HEIGHT,
      random() * WIDTH,
      random() * HEIGHT,
      random() * WIDTH,
      random() * HEIGHT,
    );
    ctx.stroke();
  }

  // 噪点。
  for (let index = 0; index < 34; index += 1) {
    ctx.fillStyle = `rgba(81, 70, 111, ${(0.08 + random() * 0.22).toFixed(3)})`;
    const size = 1 + random() * 1.6;
    ctx.fillRect(random() * WIDTH, random() * HEIGHT, size, size);
  }

  const chars = text.split("");
  const slot = WIDTH / chars.length;
  chars.forEach((char, index) => {
    ctx.save();
    ctx.translate(
      (index + 0.5) * slot + (random() - 0.5) * 7,
      HEIGHT / 2 + (random() - 0.5) * 7,
    );
    ctx.rotate((random() - 0.5) * 0.5);
    ctx.font = `700 ${19 + Math.round(random() * 6)}px ${MONO}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    const shade = random();
    ctx.fillStyle =
      shade > 0.66 ? "#8f7fc0" : shade > 0.32 ? "#51466f" : "#3d6f66";
    ctx.fillText(char, 0, 0);
    ctx.restore();
  });
}

export function PictureCode({
  expected,
  value,
  status,
  disabled,
  onChange,
  onRefresh,
}: {
  expected: string;
  value: string;
  status: "idle" | "error" | "success";
  disabled?: boolean;
  onChange: (next: string) => void;
  onRefresh: () => void;
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (canvas) paint(canvas, expected);
  }, [expected]);

  return (
    <div className="picture-code" data-status={status}>
      <span className="picture-code__label">验证码</span>
      <div className="picture-code__row">
        <button
          type="button"
          className="picture-code__plate"
          onClick={onRefresh}
          disabled={disabled}
          title="看不清？点这里换一张"
          aria-label="换一张验证码"
        >
          <canvas ref={canvasRef} aria-hidden="true" />
        </button>
        <input
          className="picture-code__input"
          type="text"
          inputMode="text"
          autoComplete="off"
          spellCheck={false}
          maxLength={4}
          placeholder="照图输入"
          value={value}
          disabled={disabled}
          aria-label="输入图里的四位验证码"
          onChange={(event) =>
            onChange(event.target.value.replace(/[^0-9a-zA-Z]/g, ""))
          }
        />
        <button
          type="button"
          className="picture-code__refresh"
          onClick={onRefresh}
          disabled={disabled}
          title="换一张"
          aria-label="换一张验证码"
        >
          <RotateCcw size={14} />
        </button>
      </div>
      {status === "error" ? (
        <small className="picture-code__note">验证码不对，换一张再试。</small>
      ) : null}
    </div>
  );
}

export default PictureCode;
