import type { KnowledgeNode } from "@leafia/shared";

/**
 * 教材节点构造器：practice 默认空数组 —— 笔记源里没有题目，这里不虚构练习，
 * 练习册由各自书目的既有题目承担。其余字段照 KnowledgeNode 原样传入。
 */
export function textbookNode(
  value: Omit<KnowledgeNode, "practice"> & {
    practice?: KnowledgeNode["practice"];
  },
): KnowledgeNode {
  return { ...value, practice: value.practice ?? [] };
}
