import {
  ArrowLeft,
  BookmarkPlus,
  Check,
  ChevronLeft,
  ChevronRight,
  CircleHelp,
  PenLine,
  RotateCcw,
  Sparkles,
  Trash2,
} from "lucide-react";
import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  type CSSProperties,
} from "react";
import { Navigate, useNavigate, useParams } from "react-router-dom";
import type { KnowledgeModule, PracticeItem } from "@leafia/shared";
import { cn } from "../../lib/cn";
import {
  knowledgeAttemptsForBook,
  knowledgeMasteryByBook,
  useKnowledge,
} from "../../store/knowledge";
import { recordStudyEvent } from "../home/studyLog";
import { TRACK_BY_BOOK } from "../practice/practiceTracks";
import { PrismCarousel } from "../reactbits/pro/prism-carousel";
import {
  knowledgeBookById,
  nodesForBook,
  practiceForBook,
} from "./knowledgeCatalog";
import {
  createKnowledgeNote,
  loadKnowledgeNotes,
  saveKnowledgeNotes,
} from "./knowledgeNotes";
import "./knowledge.css";

const pad2 = (value: number) => String(value).padStart(2, "0");

function normalizeAnswer(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[.!?。！？]+$/g, "")
    .replace(/\s+/g, " ");
}

function isCorrectAnswer(item: PracticeItem, answer: string) {
  const normalized = normalizeAnswer(answer);
  return [item.answer, ...item.acceptedAnswers].some(
    (candidate) => normalizeAnswer(candidate) === normalized,
  );
}

type ReadingPage =
  | { nodeId: string; kind: "overview" }
  | { nodeId: string; kind: "detail"; titleZh: string; bodyZh: string };

// 把一章的节点摊成连续的阅读页：每个节点先出「导读页」，再跟它的分页正文。
function readingPagesForModule(module: KnowledgeModule): ReadingPage[] {
  const pages: ReadingPage[] = [];
  for (const entry of module.nodes) {
    pages.push({ nodeId: entry.id, kind: "overview" });
    for (const page of entry.pages ?? []) {
      pages.push({
        nodeId: entry.id,
        kind: "detail",
        titleZh: page.titleZh,
        bodyZh: page.bodyZh,
      });
    }
  }
  return pages;
}

// 教材正文里的层级符（· – ◦ ▪）只做缩进，文字原样保留。
function lineDepth(line: string) {
  if (/^[·•]\s/.test(line)) return 1;
  if (/^[–—]\s/.test(line)) return 2;
  if (/^◦\s/.test(line)) return 3;
  if (/^[▪‣]\s/.test(line)) return 4;
  return 0;
}

// 「1.1.1 Definition」这类教材编号行：加粗、上面留白，像小节标题。
function lineIsSection(line: string) {
  return /^\d+(\.\d+)+\s/.test(line);
}

export function KnowledgeBookPage() {
  const { bookId } = useParams();
  const navigate = useNavigate();
  const book = knowledgeBookById(bookId);
  const hydrate = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const attempts = useKnowledge((state) => state.attempts);
  const addNodeCard = useKnowledge((state) => state.addNodeCard);
  const recordAttempt = useKnowledge((state) => state.recordAttempt);
  const [selectedModuleId, setSelectedModuleId] = useState<string | null>(null);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [practiceIndex, setPracticeIndex] = useState(0);
  const [answer, setAnswer] = useState("");
  const [feedback, setFeedback] = useState<string | null>(null);
  const [feedbackCorrect, setFeedbackCorrect] = useState<boolean | null>(null);
  // 知识卡片：读到的这一页随手写一张，卡片归到这本书下面。
  const [notes, setNotes] = useState(loadKnowledgeNotes);
  const [noteDraft, setNoteDraft] = useState("");
  const [noteIndex, setNoteIndex] = useState(0);
  // 分页阅读：知识点按页排版，右页像翻实体书一样逐页读。
  const [readingIndex, setReadingIndex] = useState(0);
  const [turnDir, setTurnDir] = useState<1 | -1>(1);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  useEffect(() => {
    if (!book) return;
    recordStudyEvent({ kind: "open", at: Date.now(), bookId: book.id });
    setSelectedModuleId(book.modules[0]?.id ?? null);
    setSelectedNodeId(book.modules[0]?.nodes[0]?.id ?? null);
    setReadingIndex(0);
    setTurnDir(1);
  }, [book]);

  const moduleIndex = Math.max(
    0,
    book?.modules.findIndex((module) => module.id === selectedModuleId) ?? 0,
  );
  const selectedModule =
    book?.modules.find((module) => module.id === selectedModuleId) ??
    book?.modules[0];

  const practiceItems = useMemo(() => {
    if (!book || !selectedModule) return [];
    if (selectedNodeId) {
      return (
        nodesForBook(book).find((node) => node.id === selectedNodeId)
          ?.practice ?? []
      );
    }
    return selectedModule.nodes.flatMap((node) => node.practice);
  }, [book, selectedModule, selectedNodeId]);

  useEffect(() => {
    setPracticeIndex(0);
    setAnswer("");
    setFeedback(null);
    setFeedbackCorrect(null);
  }, [selectedModuleId, selectedNodeId]);

  const readingPages = useMemo(
    () => (selectedModule ? readingPagesForModule(selectedModule) : []),
    [selectedModule],
  );
  const safeReadingIndex = readingPages.length
    ? Math.min(readingIndex, readingPages.length - 1)
    : 0;
  const readingPage = readingPages[safeReadingIndex];

  const turnPage = useCallback(
    (direction: 1 | -1) => {
      if (readingPages.length < 2) return;
      setTurnDir(direction);
      setReadingIndex((current) => {
        const next = current + direction;
        if (next < 0) return readingPages.length - 1;
        if (next >= readingPages.length) return 0;
        return next;
      });
    },
    [readingPages],
  );

  // 翻页后让左页目录、练习和卡片面板都跟着当前知识点走。
  useEffect(() => {
    const page = readingPages[safeReadingIndex];
    if (page && page.nodeId !== selectedNodeId) {
      setSelectedNodeId(page.nodeId);
    }
  }, [readingPages, safeReadingIndex, selectedNodeId]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.metaKey || event.ctrlKey || event.altKey || event.defaultPrevented)
        return;
      const target = event.target as HTMLElement | null;
      if (
        target &&
        (target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.tagName === "SELECT" ||
          target.isContentEditable)
      ) {
        return;
      }
      if (event.key === "ArrowRight") turnPage(1);
      else if (event.key === "ArrowLeft") turnPage(-1);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [turnPage]);

  const nodeTitles = useMemo(() => {
    const map = new Map<string, string>();
    if (book) {
      for (const node of nodesForBook(book)) {
        map.set(node.id, node.titleZh || node.title);
      }
    }
    return map;
  }, [book]);

  if (!book || !selectedModule) return <Navigate to="/library" replace />;

  const nodes = nodesForBook(book);
  const selectedNode =
    nodes.find((node) => node.id === selectedNodeId) ?? selectedModule.nodes[0];
  const nodeIndexInChapter = Math.max(
    0,
    selectedModule.nodes.findIndex((node) => node.id === selectedNode?.id),
  );
  const bookCards = cards.filter((card) => card.bookId === book.id);
  const bookAttempts = knowledgeAttemptsForBook(attempts, book.id);
  const correctAttempts = bookAttempts.filter((attempt) => attempt.correct).length;
  const accuracy = bookAttempts.length
    ? Math.round((correctAttempts / bookAttempts.length) * 100)
    : 0;
  const progress = knowledgeMasteryByBook(cards, book.id);
  const currentPractice = practiceItems[practiceIndex];
  const bookNotes = notes[book.id] ?? [];
  const noteCards = bookNotes.map((note) => ({
    id: note.id,
    title: note.title || "未命名的卡片",
    body: note.body,
    meta: `${nodeTitles.get(note.nodeId) ?? "知识卡片"} · ${new Date(
      note.createdAt,
    ).toLocaleDateString("zh-CN")}`,
  }));

  const openModule = (moduleId: string) => {
    const module = book.modules.find((entry) => entry.id === moduleId);
    if (!module) return;
    setSelectedModuleId(module.id);
    setSelectedNodeId(module.nodes[0]?.id ?? null);
    setTurnDir(1);
    setReadingIndex(0);
  };

  const saveNote = () => {
    const body = noteDraft.trim();
    if (!body || !selectedNode || !selectedModule) return;
    const note = createKnowledgeNote({
      bookId: book.id,
      moduleId: selectedModule.id,
      nodeId: selectedNode.id,
      title: selectedNode.titleZh || selectedNode.title,
      body: body.slice(0, 480),
    });
    setNotes((current) => {
      const next = {
        ...current,
        [book.id]: [note, ...(current[book.id] ?? [])],
      };
      saveKnowledgeNotes(next);
      return next;
    });
    setNoteDraft("");
    setNoteIndex(0);
    // 写卡片也是一次学习动作：记进台账，这本书会浮到「当前学习」。
    recordStudyEvent({
      kind: "topic",
      at: Date.now(),
      bookId: book.id,
      topic: selectedNode.title,
    });
  };

  const removeNote = (noteId: string) => {
    setNotes((current) => {
      const next = {
        ...current,
        [book.id]: (current[book.id] ?? []).filter((note) => note.id !== noteId),
      };
      saveKnowledgeNotes(next);
      return next;
    });
    setNoteIndex(0);
  };

  const submitPractice = () => {
    if (!currentPractice || !answer.trim()) return;
    const correct = isCorrectAnswer(currentPractice, answer);
    setFeedbackCorrect(correct);
    setFeedback(
      `${correct ? "Correct. " : "Not quite. "}${currentPractice.explanationZh}`,
    );
    recordAttempt(currentPractice, book.id, answer, correct);
    recordStudyEvent({
      kind: "knowledge-review",
      at: Date.now(),
      bookId: book.id,
      nodeId: currentPractice.nodeId,
      correct,
    });
  };

  const movePractice = () => {
    if (!practiceItems.length) return;
    setPracticeIndex((current) => (current + 1) % practiceItems.length);
    setAnswer("");
    setFeedback(null);
    setFeedbackCorrect(null);
  };

  const jumpToNode = (nodeId: string) => {
    setTurnDir(1);
    setSelectedNodeId(nodeId);
    const index = readingPages.findIndex((page) => page.nodeId === nodeId);
    if (index >= 0) setReadingIndex(index);
  };

  return (
    <main
      className="book-stage"
      style={
        {
          "--book-accent": book.accent,
          "--book-secondary": book.secondary,
        } as CSSProperties
      }
    >
      <button
        type="button"
        className="book-stage__back"
        onClick={() => navigate(`/library/${book.categoryId}`)}
        aria-label="返回知识库"
      >
        <ArrowLeft size={17} />
      </button>

      {/* 打开的书：左页目录 / 右页正文，中间是书脊 */}
      <div className="book-stage__scene">
        <div className="book3d">
          <div className="book3d__spine" aria-hidden />

          <section className="book3d__page book3d__page--left" aria-label="章节目录">
            <div className="book3d__paper">
              <header className="toc-page__head">
                <span className="toc-page__chapter-no">
                  Chapter {pad2(moduleIndex + 1)}
                </span>
                <h1>{book.title}</h1>
                <p>{book.zhTitle}</p>
              </header>

              <div className="toc-page__label">
                <span>目录</span>
                <small>Contents</small>
              </div>
              <nav className="toc-page__chapters" aria-label="章节目录">
                {book.modules.map((module, index) => (
                  <button
                    type="button"
                    key={module.id}
                    className={cn(module.id === selectedModule.id && "is-active")}
                    onClick={() => openModule(module.id)}
                  >
                    <span className="toc-page__index">{pad2(index + 1)}</span>
                    <span className="toc-page__name">
                      <strong>{module.title}</strong>
                      <small>{module.titleZh}</small>
                    </span>
                  </button>
                ))}
              </nav>

              <div className="toc-page__label toc-page__label--sub">
                <span>本章小节</span>
                <small>
                  {nodeIndexInChapter + 1} / {selectedModule.nodes.length} concepts
                </small>
              </div>
              <nav className="toc-page__nodes" aria-label="章内知识点">
                {selectedModule.nodes.map((node, index) => {
                  const saved = bookCards.some((card) => card.nodeId === node.id);
                  return (
                    <button
                      type="button"
                      key={node.id}
                      className={cn(node.id === selectedNode?.id && "is-active")}
                      onClick={() => jumpToNode(node.id)}
                    >
                      <span className="toc-page__index">{pad2(index + 1)}</span>
                      <span className="toc-page__name">
                        <strong>{node.title}</strong>
                        <small>{node.titleZh}</small>
                      </span>
                      {saved ? <Check size={13} /> : null}
                    </button>
                  );
                })}
              </nav>

              {selectedNode?.terms.length ? (
                <div className="toc-page__keywords">
                  <span className="toc-page__label-text">Keywords</span>
                  <ul>
                    {selectedNode.terms.slice(0, 6).map((term) => (
                      <li key={term}>{term}</li>
                    ))}
                  </ul>
                </div>
              ) : null}

              <footer className="toc-page__foot">
                <div className="toc-page__progress" aria-hidden>
                  <i
                    style={{
                      width: `${
                        Math.round(
                          ((nodeIndexInChapter + 1) /
                            Math.max(1, selectedModule.nodes.length)) *
                            100,
                        )
                      }%`,
                    }}
                  />
                </div>
                {TRACK_BY_BOOK[book.id] ? (
                  <button
                    type="button"
                    className="toc-page__drill"
                    onClick={() => navigate(`/drill/${TRACK_BY_BOOK[book.id]}`)}
                  >
                    去练习册做题
                  </button>
                ) : null}
              </footer>
            </div>
          </section>

          <section className="book3d__page book3d__page--right" aria-label="正文">
            <div className="book3d__paper">
              {/* 右页内容变化时，页面向左轻翻一下（不是整本书翻） */}
              <div
                key={`${selectedModule.id}-${selectedNode?.id ?? "page"}-${safeReadingIndex}`}
                className={cn("reading-flip", turnDir < 0 && "is-back")}
              >
                <header className="reading-head">
                  <span className="reading-head__no">
                    {pad2(nodeIndexInChapter + 1)}
                  </span>
                  <div className="reading-head__title">
                    <h1>{selectedNode?.titleZh || selectedNode?.title}</h1>
                    <p>{selectedNode?.title}</p>
                  </div>
                  <span className="reading-head__meta">
                    {safeReadingIndex + 1} / {Math.max(readingPages.length, 1)}
                  </span>
                </header>

                <article className="reading-body">
                  {readingPage?.kind === "detail" ? (
                    <>
                      <h2 className="reader-detail__title">
                        {readingPage.titleZh}
                      </h2>
                      <div className="reader-detail__body">
                        {readingPage.bodyZh
                          .split(/\n+/)
                          .map((line) => line.trim())
                          .filter(Boolean)
                          .map((line, lineIndex) => (
                            <p
                              key={`${lineIndex}-${line.slice(0, 16)}`}
                              className={cn(
                                "reader-line",
                                lineIsSection(line) && "is-section",
                              )}
                              data-depth={lineDepth(line)}
                            >
                              {line}
                            </p>
                          ))}
                      </div>
                    </>
                  ) : (
                    <>
                      <section className="reader-block">
                        <h3 className="reader-block__label">
                          <span className="reader-block__glyph" aria-hidden>
                            ◆
                          </span>
                          Definition
                        </h3>
                        <p className="reader-block__lead">
                          {selectedNode?.summaryZh}
                        </p>
                      </section>
                      <section className="reader-block">
                        <h3 className="reader-block__label">Original Text</h3>
                        <p className="reader-block__quote">
                          {selectedNode?.keyIdea}
                        </p>
                      </section>
                      {selectedNode?.keyPoints.length ? (
                        <section className="reader-block">
                          <h3 className="reader-block__label">Key points</h3>
                          <ul className="reader-block__points">
                            {selectedNode.keyPoints.map((point) => (
                              <li key={point}>{point}</li>
                            ))}
                          </ul>
                        </section>
                      ) : null}
                      {selectedNode?.terms.length ? (
                        <section className="reader-block reader-block--keywords">
                          <h3 className="reader-block__label">Keywords</h3>
                          <ul className="reader-block__keywords">
                            {selectedNode.terms.map((term) => (
                              <li key={term}>{term}</li>
                            ))}
                          </ul>
                        </section>
                      ) : null}
                    </>
                  )}
                </article>

                <footer className="knowledge-book-foot">
                  <button
                    type="button"
                    className="knowledge-book-save"
                    onClick={() => {
                      const node = selectedNode;
                      if (!node) return;
                      const card = addNodeCard(book.id, node.id);
                      if (!card) return;
                      recordStudyEvent({
                        kind: "card-created",
                        at: Date.now(),
                        cardId: card.id,
                        categoryId: book.categoryId,
                      });
                    }}
                  >
                    <BookmarkPlus size={14} />
                    收藏这一页
                  </button>
                  <div className="knowledge-book-turn">
                    <button
                      type="button"
                      onClick={() => turnPage(-1)}
                      aria-label="上一页"
                      disabled={readingPages.length < 2}
                    >
                      <ChevronLeft size={15} />
                    </button>
                    <span>
                      {safeReadingIndex + 1} / {Math.max(readingPages.length, 1)}
                    </span>
                    <button
                      type="button"
                      onClick={() => turnPage(1)}
                      aria-label="下一页"
                      disabled={readingPages.length < 2}
                    >
                      <ChevronRight size={15} />
                    </button>
                  </div>
                </footer>
              </div>

              <section className="knowledge-book-exercise">
                <header>
                  <span>
                    <Sparkles size={14} />
                    练习 · {accuracy}% 正确 · {progress}% 掌握
                  </span>
                  <small>
                    {practiceItems.length ? practiceIndex + 1 : 0} /{" "}
                    {practiceItems.length}
                  </small>
                </header>
                {currentPractice ? (
                  <>
                    <strong>{currentPractice.prompt}</strong>
                    {currentPractice.options.length ? (
                      <div className="knowledge-book-options">
                        {currentPractice.options.map((option) => (
                          <label key={option}>
                            <input
                              type="radio"
                              name={currentPractice.id}
                              checked={answer === option}
                              onChange={() => {
                                setAnswer(option);
                                setFeedback(null);
                                setFeedbackCorrect(null);
                              }}
                            />
                            <span>{option}</span>
                          </label>
                        ))}
                      </div>
                    ) : (
                      <input
                        value={answer}
                        onChange={(event) => {
                          setAnswer(event.target.value);
                          setFeedback(null);
                          setFeedbackCorrect(null);
                        }}
                        placeholder="Write your answer…"
                        onKeyDown={(event) => {
                          if (event.key === "Enter") submitPractice();
                        }}
                      />
                    )}
                    {feedback ? (
                      <p
                        className={cn(
                          "knowledge-book-feedback",
                          feedbackCorrect === false && "is-wrong",
                        )}
                      >
                        {feedback}
                      </p>
                    ) : null}
                    <div className="knowledge-book-exercise__actions">
                      {feedback ? (
                        <button type="button" onClick={movePractice}>
                          <RotateCcw size={14} />
                          下一题
                        </button>
                      ) : (
                        <button
                          type="button"
                          disabled={!answer.trim()}
                          onClick={submitPractice}
                        >
                          <CircleHelp size={14} />
                          检查答案
                        </button>
                      )}
                    </div>
                  </>
                ) : (
                  <p className="knowledge-book-empty">
                    这一章还没有练习题。切换到其它章节继续。
                  </p>
                )}
              </section>

              <section className="knowledge-book-notes">
                <header>
                  <span>
                    <PenLine size={14} />
                    知识卡片 · {bookNotes.length} 张
                  </span>
                  <small>
                    {selectedNode
                      ? `正在读：${selectedNode.titleZh || selectedNode.title}`
                      : ""}
                  </small>
                </header>
                <div className="knowledge-book-notes__composer">
                  <textarea
                    value={noteDraft}
                    rows={2}
                    maxLength={480}
                    placeholder="这一页让你想到什么？写成一张卡片 —— 以后翻卡片就能回到这里。"
                    onChange={(event) => setNoteDraft(event.target.value)}
                    onKeyDown={(event) => {
                      if (
                        (event.metaKey || event.ctrlKey) &&
                        event.key === "Enter"
                      ) {
                        saveNote();
                      }
                    }}
                  />
                  <button
                    type="button"
                    disabled={!noteDraft.trim()}
                    onClick={saveNote}
                  >
                    <BookmarkPlus size={14} />
                    记下这张卡片
                  </button>
                </div>
                <PrismCarousel
                  items={noteCards}
                  activeIndex={Math.min(
                    noteIndex,
                    Math.max(0, noteCards.length - 1),
                  )}
                  onActiveChange={setNoteIndex}
                  onSelect={(card) => {
                    const note = bookNotes.find((entry) => entry.id === card.id);
                    if (!note) return;
                    const module = book.modules.find(
                      (entry) => entry.id === note.moduleId,
                    );
                    if (module) {
                      setSelectedModuleId(module.id);
                      const pageIndex = readingPagesForModule(module).findIndex(
                        (page) => page.nodeId === note.nodeId,
                      );
                      if (pageIndex >= 0) setReadingIndex(pageIndex);
                      setTurnDir(1);
                    }
                    setSelectedNodeId(note.nodeId);
                  }}
                  emptyLabel="还没有卡片。读到有感觉的一页，在上面的框里写一句。"
                />
                {bookNotes.length ? (
                  <button
                    type="button"
                    className="knowledge-book-notes__delete"
                    onClick={() => {
                      const note = bookNotes[noteIndex];
                      if (note) removeNote(note.id);
                    }}
                  >
                    <Trash2 size={13} />
                    删除这一张
                  </button>
                ) : null}
              </section>
            </div>
          </section>
        </div>
      </div>
    </main>
  );
}
