import {
  ArrowLeft,
  ArrowRight,
  Check,
  LoaderCircle,
  LogOut,
  Mail,
  Phone,
  ShieldCheck,
  UserRound,
  X,
} from "lucide-react";
import {
  useEffect,
  useId,
  useRef,
  useState,
  type FormEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { Link, useNavigate } from "react-router-dom";
import { useLeafiaAccount } from "../../lib/auth";
import {
  isChinesePhone,
  isStrongPassword,
  isValidEmail,
  normalizeEmail,
} from "../../lib/authForm";
import { cn } from "../../lib/cn";
import { CodeSlots } from "../reactbits/vendor";
import {
  makePictureCode,
  matchesPictureCode,
  PictureCode,
} from "./PictureCode";
import "./auth-dialog.css";

type AuthView = "signin" | "register";
type LoginMode = "password" | "sms";
type CodeStatus = "idle" | "error" | "success";

interface AuthDialogProps {
  open: boolean;
  onClose: () => void;
  initialView?: AuthView;
}

function FieldIcon({ children }: { children: ReactNode }) {
  return (
    <span className="auth-dialog__field-icon" aria-hidden="true">
      {children}
    </span>
  );
}

function CodeField({
  label,
  value,
  status,
  disabled,
  autoFocus,
  ariaLabel,
  onChange,
  onComplete,
}: {
  label: string;
  value: string;
  status: CodeStatus;
  disabled?: boolean;
  autoFocus?: boolean;
  ariaLabel: string;
  onChange: (value: string) => void;
  onComplete?: (value: string) => void;
}) {
  return (
    <label className="auth-dialog__code-field">
      <span>{label}</span>
      <CodeSlots
        length={6}
        value={value}
        status={status}
        disabled={disabled}
        autoFocus={autoFocus}
        mask
        slotSize={46}
        gap={8}
        radius={8}
        ariaLabel={ariaLabel}
        accentColor="#8f7fc0"
        inkColor="#51466f"
        slotColor="#e8e3f1"
        digitColor="#342c36"
        dangerColor="#a25151"
        onChange={(next: string) => onChange(next)}
        onComplete={(code: string) => onComplete?.(code)}
      />
    </label>
  );
}

export function AuthDialog({
  open,
  onClose,
  initialView = "signin",
}: AuthDialogProps) {
  const account = useLeafiaAccount();
  const navigate = useNavigate();
  const titleId = useId();
  const restoreFocusRef = useRef<HTMLElement | null>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  /**
   * 关窗那一下走 ref，不走依赖数组：下面那支「开窗时重置」的 effect 每次
   * 重跑都会 clearError()，而调用方大多把 onClose 写成内联箭头函数 ——
   * 谁要是碰巧又订着整个账号 store，一次 set 就能让整页重画、生出一个
   * 新的 onClose，effect 再重跑，来回就是死循环（React #185 白屏）。
   * ref 让 Escape 永远读到最新的回调，又不会把 onClose 拖进依赖里。
   */
  const onCloseRef = useRef(onClose);
  useEffect(() => {
    onCloseRef.current = onClose;
  }, [onClose]);

  const [view, setView] = useState<AuthView>(initialView);
  const [loginMode, setLoginMode] = useState<LoginMode>("password");
  const [displayName, setDisplayName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [pinStatus, setPinStatus] = useState<CodeStatus>("idle");
  const [confirmStatus, setConfirmStatus] = useState<CodeStatus>("idle");
  // 注册那一步的图形验证码：答案在内存里，图是本机画的。
  const [pictureCode, setPictureCode] = useState(() => makePictureCode());
  const [pictureInput, setPictureInput] = useState("");
  const [pictureStatus, setPictureStatus] = useState<CodeStatus>("idle");
  const [phone, setPhone] = useState("");
  const [code, setCode] = useState("");
  const [codeStatus, setCodeStatus] = useState<CodeStatus>("idle");
  const [codeSent, setCodeSent] = useState(false);
  const [bindOpen, setBindOpen] = useState(false);
  const [bindPhone, setBindPhone] = useState("");
  const [bindCode, setBindCode] = useState("");
  const [bindCodeStatus, setBindCodeStatus] = useState<CodeStatus>("idle");
  const [bindCodeSent, setBindCodeSent] = useState(false);
  const [localMessage, setLocalMessage] = useState<string | null>(null);

  const emailReady = isValidEmail(email);
  const passwordsMatch =
    password.length === 6 && password === confirmPassword;
  const pictureReady = matchesPictureCode(pictureInput, pictureCode);
  const registerReady =
    displayName.trim().length >= 2 &&
    emailReady &&
    isStrongPassword(password) &&
    passwordsMatch;
  const loginReady = emailReady && isStrongPassword(password);
  const phoneReady = isChinesePhone(phone);
  const bindPhoneReady = isChinesePhone(bindPhone);

  useEffect(() => {
    if (!open) return undefined;
    restoreFocusRef.current = document.activeElement as HTMLElement | null;
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    setView(initialView);
    setLocalMessage(null);
    setCodeSent(false);
    setBindOpen(false);
    setBindCodeSent(false);
    refreshPictureCode();
    account.clearError();
    const focusTimer = window.setTimeout(
      () => emailRef.current?.focus(),
      80,
    );
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onCloseRef.current();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.clearTimeout(focusTimer);
      window.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = originalOverflow;
      restoreFocusRef.current?.focus();
    };
  }, [account.clearError, initialView, open]);

  if (!open || typeof document === "undefined") return null;

  const flashStatus = (
    setter: (status: CodeStatus) => void,
    status: Exclude<CodeStatus, "idle">,
  ) => {
    setter(status);
    window.setTimeout(() => setter("idle"), status === "success" ? 700 : 950);
  };

  const switchView = (next: AuthView) => {
    setView(next);
    setLocalMessage(null);
    setPinStatus("idle");
    setConfirmStatus("idle");
    // 每回到注册页都换一张，上来那张可能已经被人看过了。
    refreshPictureCode();
    account.clearError();
  };

  const switchLoginMode = (next: LoginMode) => {
    setLoginMode(next);
    setCodeStatus("idle");
    setLocalMessage(null);
    account.clearError();
  };

  const submitPinLogin = async (submitted = password) => {
    if (!emailReady || !isStrongPassword(submitted) || account.busy) return;
    setPinStatus("idle");
    const succeeded = await account.signInWithPassword({
      email: normalizeEmail(email),
      password: submitted,
    });
    flashStatus(setPinStatus, succeeded ? "success" : "error");
    if (!succeeded) setPassword("");
  };

  const submitPasswordLogin = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await submitPinLogin();
  };

  const refreshPictureCode = () => {
    setPictureCode(makePictureCode());
    setPictureInput("");
    setPictureStatus("idle");
  };

  const submitRegister = async (
    submittedPassword = password,
    submittedConfirm = confirmPassword,
  ) => {
    if (
      displayName.trim().length < 2 ||
      !emailReady ||
      !isStrongPassword(submittedPassword) ||
      submittedConfirm !== submittedPassword ||
      account.busy
    ) {
      return;
    }
    // 验证码先行：不对就换一张，别拿它去撞后端。
    if (!matchesPictureCode(pictureInput, pictureCode)) {
      setPictureCode(makePictureCode());
      setPictureInput("");
      setPictureStatus("error");
      window.setTimeout(() => setPictureStatus("idle"), 2200);
      return;
    }
    setPictureStatus("idle");
    setPinStatus("idle");
    setConfirmStatus("idle");
    const succeeded = await account.registerWithPassword({
      displayName: displayName.trim(),
      email: normalizeEmail(email),
      password: submittedPassword,
    });
    flashStatus(setPinStatus, succeeded ? "success" : "error");
    flashStatus(setConfirmStatus, succeeded ? "success" : "error");
    if (!succeeded) {
      setPassword("");
      setConfirmPassword("");
      refreshPictureCode();
      return;
    }
    // 注册即登录：窗口收起来，人直接落到书架上。
    setLocalMessage("账号已就绪，正在打开书架……");
    window.setTimeout(() => {
      onClose();
      navigate("/shelf");
    }, 560);
  };

  const submitRegisterForm = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await submitRegister(password, confirmPassword);
  };

  const sendLoginCode = async () => {
    if (!phoneReady || account.busy) return;
    if (await account.sendCode(phone)) setCodeSent(true);
  };

  const submitSmsCode = async (submitted = code) => {
    if (!codeSent || submitted.length !== 6 || account.busy) return;
    const succeeded = await account.signInWithCode(phone, submitted);
    flashStatus(setCodeStatus, succeeded ? "success" : "error");
    if (!succeeded) setCode("");
  };

  const sendBindCode = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!bindPhoneReady || account.busy) return;
    if (await account.requestPhoneBind(bindPhone)) setBindCodeSent(true);
  };

  const submitBindCode = async (submitted = bindCode) => {
    if (!bindCodeSent || submitted.length !== 6 || account.busy) return;
    const succeeded = await account.verifyPhoneBind(bindPhone, submitted);
    flashStatus(setBindCodeStatus, succeeded ? "success" : "error");
    if (succeeded) {
      setBindOpen(false);
      setBindCode("");
      setBindCodeSent(false);
      setLocalMessage("手机号已绑定，之后也可以用验证码登录。");
    } else {
      setBindCode("");
    }
  };

  const signOut = async () => {
    await account.signOut();
    onClose();
  };

  const accountPanel = account.user ? (
    <div className="auth-dialog__account-panel">
      <div className="auth-dialog__profile">
        <span className="auth-dialog__avatar" aria-hidden="true">
          {account.user.displayName.trim().slice(0, 1).toUpperCase() || "I"}
        </span>
        <span>
          <small>Signed in</small>
          <strong>{account.user.displayName}</strong>
          <em>
            {account.user.emailMasked ??
              account.user.phoneMasked ??
              "Leafia Account"}
          </em>
        </span>
      </div>

      <div className="auth-dialog__account-facts">
        <p>
          <Mail size={15} aria-hidden="true" />
          <span>
            <small>邮箱</small>
            <strong>{account.user.emailMasked ?? "未绑定邮箱"}</strong>
          </span>
          {account.user.emailMasked ? (
            <Check size={15} aria-label="已绑定" />
          ) : null}
        </p>
        <p>
          <Phone size={15} aria-hidden="true" />
          <span>
            <small>手机号</small>
            <strong>{account.user.phoneMasked ?? "未绑定手机号"}</strong>
          </span>
          {account.user.phoneMasked ? (
            <Check size={15} aria-label="已绑定" />
          ) : (
            <button type="button" onClick={() => setBindOpen(true)}>
              去绑定
            </button>
          )}
        </p>
      </div>

      {bindOpen ? (
        <div className="auth-dialog__bind">
          <header>
            <strong>绑定手机号</strong>
            <button type="button" onClick={() => setBindOpen(false)}>
              稍后
            </button>
          </header>
          <form onSubmit={sendBindCode}>
            <label className="auth-dialog__input">
              <FieldIcon>
                <Phone size={16} />
              </FieldIcon>
              <input
                type="tel"
                inputMode="numeric"
                autoComplete="tel"
                maxLength={11}
                placeholder="手机号"
                value={bindPhone}
                onChange={(event) => {
                  setBindPhone(
                    event.target.value.replace(/\D/g, "").slice(0, 11),
                  );
                  setBindCodeSent(false);
                  setLocalMessage(null);
                  account.clearError();
                }}
              />
              <button type="submit" disabled={account.busy || !bindPhoneReady}>
                {bindCodeSent ? "重新发送" : "发送验证码"}
              </button>
            </label>
          </form>
          {bindCodeSent ? (
            <div className="auth-dialog__bind-code">
              <CodeField
                label="验证码"
                value={bindCode}
                status={bindCodeStatus}
                disabled={account.busy}
                ariaLabel="绑定手机验证码"
                onChange={(next) => {
                  setBindCode(next);
                  account.clearError();
                }}
                onComplete={(next) => void submitBindCode(next)}
              />
              <button
                type="button"
                className="auth-dialog__submit"
                disabled={account.busy || bindCode.length !== 6}
                onClick={() => void submitBindCode()}
              >
                确认绑定
              </button>
            </div>
          ) : null}
          {account.devCode ? (
            <p className="auth-dialog__hint">
              开发环境验证码：<strong>{account.devCode}</strong>
            </p>
          ) : null}
        </div>
      ) : null}

      {localMessage ? (
        <p className="auth-dialog__success" role="status">
          <Check size={14} aria-hidden="true" />
          {localMessage}
        </p>
      ) : null}

      <div className="auth-dialog__account-actions">
        <button type="button" className="is-quiet" onClick={onClose}>
          继续使用
        </button>
        <button
          type="button"
          className="is-danger"
          disabled={account.busy}
          onClick={() => void signOut()}
        >
          <LogOut size={15} aria-hidden="true" />
          退出登录
        </button>
      </div>
    </div>
  ) : null;

  const passwordLogin = (
    <form className="auth-dialog__form" onSubmit={submitPasswordLogin}>
      <label>
        <span>邮箱</span>
        <span className="auth-dialog__input">
          <FieldIcon>
            <Mail size={16} />
          </FieldIcon>
          <input
            ref={emailRef}
            type="email"
            autoComplete="email"
            placeholder="name@example.com"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              account.clearError();
            }}
          />
        </span>
      </label>
      <CodeField
        label="六位密码"
        value={password}
        status={pinStatus}
        disabled={account.busy}
        ariaLabel="六位数字密码"
        onChange={(next) => {
          setPassword(next);
          account.clearError();
        }}
        onComplete={(next) => void submitPinLogin(next)}
      />
      <small className="auth-dialog__rule">
        密码由 6 位数字组成。输入完成后自动登录。
      </small>
      <button
        type="submit"
        className="auth-dialog__submit"
        disabled={account.busy || !loginReady}
      >
        {account.busy ? (
          <LoaderCircle className="is-spinning" size={16} />
        ) : (
          <ArrowRight size={16} />
        )}
        登录
      </button>
    </form>
  );

  const smsLogin = (
    <div className="auth-dialog__form">
      {!codeSent ? (
        <>
          <label>
            <span>手机号</span>
            <span className="auth-dialog__input">
              <FieldIcon>
                <Phone size={16} />
              </FieldIcon>
              <input
                ref={emailRef}
                type="tel"
                inputMode="numeric"
                autoComplete="tel"
                maxLength={11}
                placeholder="11 位手机号"
                value={phone}
                onChange={(event) => {
                  setPhone(event.target.value.replace(/\D/g, "").slice(0, 11));
                  account.clearError();
                }}
              />
            </span>
          </label>
          <button
            type="button"
            className="auth-dialog__submit"
            disabled={account.busy || !phoneReady}
            onClick={() => void sendLoginCode()}
          >
            获取验证码
          </button>
        </>
      ) : (
        <>
          <div className="auth-dialog__code-head">
            <button type="button" onClick={() => setCodeSent(false)}>
              <ArrowLeft size={15} />
              返回手机号
            </button>
            <span>{phone.replace(/(\d{3})\d{4}(\d{4})/, "$1****$2")}</span>
          </div>
          <CodeField
            label="六位验证码"
            value={code}
            status={codeStatus}
            disabled={account.busy}
            autoFocus
            ariaLabel="六位手机验证码"
            onChange={(next) => {
              setCode(next);
              account.clearError();
            }}
            onComplete={(next) => void submitSmsCode(next)}
          />
          {account.devCode ? (
            <p className="auth-dialog__hint">
              开发环境验证码：<strong>{account.devCode}</strong>
            </p>
          ) : null}
          <div className="auth-dialog__code-actions">
            <button type="button" onClick={() => void sendLoginCode()}>
              重新发送
            </button>
            <button
              type="button"
              className="auth-dialog__submit"
              disabled={account.busy || code.length !== 6}
              onClick={() => void submitSmsCode()}
            >
              登录
            </button>
          </div>
        </>
      )}
    </div>
  );

  const registerForm = (
    <form className="auth-dialog__form" onSubmit={submitRegisterForm}>
      <label>
        <span>昵称</span>
        <span className="auth-dialog__input">
          <FieldIcon>
            <UserRound size={16} />
          </FieldIcon>
          <input
            ref={emailRef}
            type="text"
            autoComplete="nickname"
            maxLength={24}
            placeholder="怎么称呼你"
            value={displayName}
            onChange={(event) => {
              setDisplayName(event.target.value);
              account.clearError();
            }}
          />
        </span>
      </label>
      <label>
        <span>邮箱</span>
        <span className="auth-dialog__input">
          <FieldIcon>
            <Mail size={16} />
          </FieldIcon>
          <input
            type="email"
            autoComplete="email"
            maxLength={254}
            placeholder="name@example.com"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              account.clearError();
            }}
          />
        </span>
      </label>
      <CodeField
        label="六位密码"
        value={password}
        status={pinStatus}
        disabled={account.busy}
        ariaLabel="设置六位数字密码"
        onChange={(next) => {
          setPassword(next);
          account.clearError();
        }}
        onComplete={(next) => {
          // 最后一位按完就顺手提交，是老规矩；但验证码排在密码后面，
          // 这会儿多半还没填 —— 没填对就不抢跑，等「创建账号」那颗按钮。
          if (confirmPassword.length === 6 && pictureReady) {
            void submitRegister(next, confirmPassword);
          }
          else setPinStatus("success");
        }}
      />
      <CodeField
        label="确认密码"
        value={confirmPassword}
        status={confirmStatus}
        disabled={account.busy}
        ariaLabel="确认六位数字密码"
        onChange={(next) => {
          setConfirmPassword(next);
          account.clearError();
        }}
        onComplete={(next) => {
          if (password.length === 6 && next === password && pictureReady) {
            void submitRegister(password, next);
          }
        }}
      />
      {confirmPassword && !passwordsMatch ? (
        <small className="auth-dialog__rule">两次输入的密码不一致</small>
      ) : null}
      {/* 图形验证码：图是本机画的，答案只在内存里。填错了提交时换一张重来；
          填对了当场亮绿。 */}
      <PictureCode
        expected={pictureCode}
        value={pictureInput}
        status={
          pictureStatus === "error" ? "error" : pictureReady ? "success" : "idle"
        }
        disabled={account.busy}
        onChange={(next) => {
          setPictureInput(next);
          account.clearError();
        }}
        onRefresh={refreshPictureCode}
      />
      <button
        type="submit"
        className="auth-dialog__submit"
        disabled={account.busy || !registerReady}
      >
        {account.busy ? (
          <LoaderCircle className="is-spinning" size={16} />
        ) : (
          <ArrowRight size={16} />
        )}
        创建账号
      </button>
    </form>
  );

  return createPortal(
    <div className="auth-dialog auth-dialog--fullscreen">
      <button
        type="button"
        className="auth-dialog__scrim"
        aria-label="关闭登录窗口"
        onClick={onClose}
      />
      <div className="auth-dialog__wash" aria-hidden="true">
        <span className="auth-dialog__note" data-note="0">
          ♪
        </span>
        <span className="auth-dialog__note" data-note="1">
          ♩
        </span>
        <span className="auth-dialog__note" data-note="2">
          ♫
        </span>
        <span className="auth-dialog__note" data-note="3">
          ♬
        </span>
      </div>
      <section
        className="auth-dialog__panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
      >
        <button
          type="button"
          className="auth-dialog__close"
          aria-label="关闭"
          onClick={onClose}
        >
          <X size={18} />
        </button>

        <aside className="auth-dialog__aside">
          <div className="auth-dialog__brand">
            <img src="/leafia-mark.svg" alt="" />
            <span>
              <strong>Leafia</strong>
              <small>Moonlit knowledge space</small>
            </span>
          </div>
          <div className="auth-dialog__aside-copy">
            <span className="auth-dialog__eyebrow">Language in motion</span>
            <h2 id={titleId}>
              {accountPanel
                ? "账号空间"
                : view === "register"
                  ? "建立你的书架"
                  : "回到你的书架"}
            </h2>
            <p>
              {accountPanel
                ? "邮箱和绑定手机指向同一个账号，换设备登录后便条仍会恢复。"
                : "从首页直接进入，不离开当前页面；关闭后回到原来的位置。"}
            </p>
          </div>
          <div className="auth-dialog__staff" aria-hidden="true">
            {Array.from({ length: 5 }, (_, index) => (
              <i key={index} />
            ))}
            <span>♪</span>
          </div>
        </aside>

        <div className="auth-dialog__main">
          {accountPanel ? (
            accountPanel
          ) : (
            <>
              <div className="auth-dialog__tabs" role="tablist">
                <button
                  type="button"
                  role="tab"
                  aria-selected={view === "signin"}
                  className={view === "signin" ? "is-active" : ""}
                  onClick={() => switchView("signin")}
                >
                  登录
                </button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={view === "register"}
                  className={view === "register" ? "is-active" : ""}
                  onClick={() => switchView("register")}
                >
                  注册
                </button>
              </div>

              {view === "signin" ? (
                <>
                  <div className="auth-dialog__mode-switch">
                    <button
                      type="button"
                      className={loginMode === "password" ? "is-active" : ""}
                      onClick={() => switchLoginMode("password")}
                    >
                      密码登录
                    </button>
                    <button
                      type="button"
                      className={loginMode === "sms" ? "is-active" : ""}
                      onClick={() => switchLoginMode("sms")}
                    >
                      验证码登录
                    </button>
                  </div>
                  {loginMode === "password" ? passwordLogin : smsLogin}
                </>
              ) : (
                registerForm
              )}

              {account.error ? (
                <p className="auth-dialog__error" role="alert">
                  {account.error}
                </p>
              ) : null}

              <p className="auth-dialog__switch-copy">
                {view === "signin" ? "还没有账号？" : "已经有账号？"}
                <button
                  type="button"
                  onClick={() =>
                    switchView(view === "signin" ? "register" : "signin")
                  }
                >
                  {view === "signin" ? "创建账号" : "返回登录"}
                </button>
              </p>
            </>
          )}
        </div>
      </section>
    </div>,
    document.body,
  );
}
