/**
 * 旧品牌 → Leafia 的一次性本地数据迁移。
 *
 * main.tsx 的第一行 import 它：在任何 store 模块读到 localStorage 之前，
 * 同步把旧前缀的键整批搬到新前缀，老用户的数据（账号、皮肤、收藏、设置等）
 * 不丢，也不用手动清缓存。
 *
 * IndexedDB（idb-keyval 默认库，键名与 localStorage 同名）不便在启动时同步搬，
 * 由三个 store 的 hydrate 读点改走 idbGetWithLegacyFallback()：新键没有时
 * 回落到旧键并把数据顺势写进新键。
 */
import { get as idbGet, set as idbSet } from "idb-keyval";

/** 仅此一处保留旧品牌前缀，用于兼容历史本地数据；新代码一律用 "leafia"。 */
const LEGACY_BRAND = "inkflow";
const CURRENT_BRAND = "leafia";

function toLegacyKey(key: string): string {
  return key.startsWith(CURRENT_BRAND)
    ? LEGACY_BRAND + key.slice(CURRENT_BRAND.length)
    : key;
}

/** 把旧前缀（"<旧品牌>:" / "<旧品牌>."）的 localStorage 键搬到新前缀；新键已存在则不覆盖。 */
function migrateLocalStorage(): void {
  const storage = window.localStorage;
  const moves: Array<[string, string]> = [];
  for (let i = 0; i < storage.length; i += 1) {
    const key = storage.key(i);
    if (!key) continue;
    if (
      key === LEGACY_BRAND ||
      key.startsWith(`${LEGACY_BRAND}:`) ||
      key.startsWith(`${LEGACY_BRAND}.`)
    ) {
      moves.push([key, CURRENT_BRAND + key.slice(LEGACY_BRAND.length)]);
    }
  }
  for (const [legacyKey, currentKey] of moves) {
    const value = storage.getItem(legacyKey);
    if (value === null) continue;
    if (storage.getItem(currentKey) === null) {
      storage.setItem(currentKey, value);
    }
    storage.removeItem(legacyKey);
  }
}

/** 先读新键；没有则读旧键，读到就把数据搬进新键（旧键留着不管，IndexedDB 空间不值钱）。 */
export async function idbGetWithLegacyFallback<T>(
  key: string,
): Promise<T | undefined> {
  const current = await idbGet<T>(key).catch(() => undefined);
  if (current !== undefined) return current;
  const legacy = await idbGet<T>(toLegacyKey(key)).catch(() => undefined);
  if (legacy === undefined) return undefined;
  void idbSet(key, legacy).catch(() => undefined);
  return legacy;
}

try {
  migrateLocalStorage();
} catch {
  // localStorage 不可用（隐私模式等）时静默跳过，不阻断启动。
}
