import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { ReactLenis, useLenis } from "lenis/react";
import {
  type ReactNode,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { useLocation } from "react-router-dom";
import "lenis/dist/lenis.css";
import {
  AmbientBackdrop,
  preloadAmbientEffects,
} from "../components/ambient/AmbientBackdrop";
import {
  MOTION_SELECTORS,
  getMotionSurface,
  shouldAnimateRoute,
  shouldShowAmbientBackdrop,
} from "./motionConfig";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

gsap.registerPlugin(ScrollTrigger);

const LENIS_OPTIONS = {
  autoRaf: false,
  autoToggle: true,
  allowNestedScroll: true,
  lerp: 0.085,
  overscroll: true,
  smoothWheel: true,
  stopInertiaOnNavigate: true,
  syncTouch: false,
  respectReducedMotion: true,
} as const;

function LenisGsapBridge() {
  const lenis = useLenis(ScrollTrigger.update);

  useEffect(() => {
    if (!lenis) return undefined;
    const update = (time: number) => lenis.raf(time * 1000);
    gsap.ticker.add(update);
    gsap.ticker.lagSmoothing(0);
    const refreshTimer = window.setTimeout(() => ScrollTrigger.refresh(), 120);

    return () => {
      window.clearTimeout(refreshTimer);
      gsap.ticker.remove(update);
      gsap.ticker.lagSmoothing(500, 33);
    };
  }, [lenis]);

  return null;
}

function MotionRouteController({
  routeKey,
  pathname,
}: {
  routeKey: string;
  pathname: string;
}) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const surface = getMotionSurface(pathname);

  useLayoutEffect(() => {
    const routeRoot = document.querySelector<HTMLElement>(MOTION_SELECTORS.root);
    if (!routeRoot || prefersReducedMotion || !shouldAnimateRoute(surface)) {
      gsap.set(routeRoot || {}, { clearProps: "opacity,visibility,transform,filter" });
      return undefined;
    }

    const context = gsap.context(() => {
      const timeline = gsap.timeline({
        defaults: { duration: 0.52, ease: "power3.out" },
      });

      timeline.fromTo(
        routeRoot,
        { autoAlpha: 0, filter: "blur(8px)", y: 14 },
        { autoAlpha: 1, filter: "blur(0px)", y: 0 },
      );

      const enterTargets = gsap.utils.toArray<HTMLElement>(
        MOTION_SELECTORS.enter,
        routeRoot,
      );
      enterTargets.forEach((element, index) => {
        timeline.fromTo(
          element,
          { autoAlpha: 0, y: 22 },
          { autoAlpha: 1, y: 0, duration: 0.48 },
          index === 0 ? 0.08 : "<0.08",
        );
      });

      gsap.utils
        .toArray<HTMLElement>(MOTION_SELECTORS.stagger, routeRoot)
        .forEach((container) => {
          const children = Array.from(container.children).filter(
            (child): child is HTMLElement => child instanceof HTMLElement,
          );
          if (!children.length) return;
          gsap.fromTo(
            children,
            { autoAlpha: 0, y: 20 },
            {
              autoAlpha: 1,
              y: 0,
              duration: 0.52,
              stagger: 0.065,
              ease: "power3.out",
              scrollTrigger: {
                trigger: container,
                start: "top 88%",
                once: true,
              },
            },
          );
        });

      gsap.utils
        .toArray<HTMLElement>(MOTION_SELECTORS.parallax, routeRoot)
        .forEach((element) => {
          gsap.fromTo(
            element,
            { yPercent: -3 },
            {
              yPercent: 3,
              ease: "none",
              scrollTrigger: {
                trigger: element,
                start: "top bottom",
                end: "bottom top",
                scrub: 0.8,
              },
            },
          );
        });

      const pageTurnTarget = routeRoot.querySelector<HTMLElement>(
        MOTION_SELECTORS.pageTurn,
      );
      if (pageTurnTarget) {
        gsap.fromTo(
          pageTurnTarget,
          {
            autoAlpha: 0.68,
            rotationX: 3.2,
            transformOrigin: "50% 0%",
            y: 26,
          },
          {
            autoAlpha: 1,
            rotationX: 0,
            y: 0,
            duration: 0.62,
            ease: "power3.out",
            clearProps: "transform,filter",
          },
        );
      }
    }, routeRoot);

    const refreshFrame = requestAnimationFrame(() => ScrollTrigger.refresh());
    return () => {
      cancelAnimationFrame(refreshFrame);
      context.revert();
    };
  }, [routeKey, pathname, prefersReducedMotion, surface]);

  return null;
}

function RouteTransitionLayer({
  routeKey,
  pathname,
}: {
  routeKey: string;
  pathname: string;
}) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const previousKey = useRef(routeKey);
  const transitionTimer = useRef<number | null>(null);
  const [active, setActive] = useState(false);

  useEffect(() => {
    if (previousKey.current === routeKey) return undefined;
    previousKey.current = routeKey;
    const surface = getMotionSurface(pathname);
    if (prefersReducedMotion || !shouldShowAmbientBackdrop(surface)) {
      if (transitionTimer.current !== null) {
        window.clearTimeout(transitionTimer.current);
      }
      setActive(false);
      return undefined;
    }

    if (transitionTimer.current !== null) {
      window.clearTimeout(transitionTimer.current);
    }
    setActive(true);
    transitionTimer.current = window.setTimeout(() => {
      transitionTimer.current = null;
      setActive(false);
    }, 820);
    return undefined;
  }, [routeKey, pathname, prefersReducedMotion]);

  useEffect(
    () => () => {
      if (transitionTimer.current !== null) {
        window.clearTimeout(transitionTimer.current);
      }
    },
    [],
  );

  return (
    <AmbientBackdrop
      className="motion-transition-layer"
      variant="fog"
      active={active}
      aria-hidden="true"
      data-route-key={routeKey}
    />
  );
}

export function MotionSystem({ children }: { children: ReactNode }) {
  const location = useLocation();
  const routeKey = `${location.pathname}${location.search}`;
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    if (prefersReducedMotion) return undefined;
    const timer = window.setTimeout(() => {
      void preloadAmbientEffects();
    }, 1_200);
    return () => window.clearTimeout(timer);
  }, [prefersReducedMotion]);

  return (
    <ReactLenis root options={LENIS_OPTIONS}>
      <LenisGsapBridge />
      <MotionRouteController
        routeKey={routeKey}
        pathname={location.pathname}
      />
      <RouteTransitionLayer
        routeKey={routeKey}
        pathname={location.pathname}
      />
      {/* 点击绽开的火花特效已移除：画布层压在目录面板之上，点菜单也会炸开一圈，
          而它并不承担任何信息（原 ClickSpark 仍在 vendor/ 里留着）。
          这一层壳保留下来，只是让页面继续有一个 100dvh 的定位容器。 */}
      <div className="motion-shell">{children}</div>
    </ReactLenis>
  );
}
