import { gsap } from "gsap";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";
import "./depth-carousel.css";

/**
 * Depth Carousel —— 一排卡片沿着深度轴摆成的转盘。
 *
 * 借自 React Bits Pro 的同名组件（images receding down a depth axis，中间
 * 那张正对镜头，后面的往斜后方一层层退、变小变淡）。这里不摆图片，摆的
 * 是「背过的卡片」：每张卡就是一枚单词卡（词 + 释义 + 复习轮次），卡面用
 * 主题色画出来，换皮肤时整盘卡跟着走。
 *
 * 四种输入：
 *   - 拖动       → 把转盘拨过去，松手按惯性停在最近的格子上
 *   - 滚轮       → 一格一格翻
 *   - ← → 方向键 → 同上
 *   - 点卡片     → 不是中间那张就先转正；已经是中间那张才真的打开它
 *
 * prefers-reduced-motion 或者窄屏时退成平铺网格：同样的卡片，一屏看全，
 * 不转、不缩、不糊。
 */

export interface DepthCarouselItem {
  id: string;
  /** 卡面上的主词（有图时只给读屏用）。 */
  word: string;
  /** 词性/来源这类一两个字的标记。 */
  tag?: string;
  /** 释义或用例，一行到两行。 */
  meaning?: string;
  /** 已复习轮次；卡面右下角的小字。 */
  rounds?: number;
  /** 有图就铺满整张卡当卡面（比如学习卡），文字不再叠一层。 */
  image?: string;
}

interface DepthCarouselProps {
  items: DepthCarouselItem[];
  onSelect?: (item: DepthCarouselItem) => void;
  className?: string;
  emptyLabel?: string;
}

/** 卡片尺寸。转盘是按这几位数算的，别只改 CSS 里的宽高。 */
const CARD_WIDTH = 208;
const CARD_HEIGHT = 264;
/** 后面每退一层往后走多远、往旁边挪多远、转多少度。 */
const DEPTH = 210;
const SPREAD = 86;
const TILT = 20;
/** 同时还能看见几张（再多就直接隐掉，省得白算）。 */
const VISIBLE = 4;
/** 每退一层暗多少、糊多少。 */
const FALLOFF = 0.2;
const BLUR = 5;
/** 翻页补间时长（秒）。 */
const DURATION = 0.62;
const EASE = "power3.out";

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

/** 由字符串算一个稳定的 0..1 伪随机数：同一张卡每次都是同一种颜色。 */
function hash01(input: string, salt: number) {
  let hash = 2166136261 ^ salt;
  for (let index = 0; index < input.length; index += 1) {
    hash = Math.imul(hash ^ input.charCodeAt(index), 16777619);
  }
  hash ^= hash >>> 15;
  return ((hash >>> 0) % 100000) / 100000;
}

export function DepthCarousel({
  items,
  onSelect,
  className = "",
  emptyLabel = "还没有背过的卡片。去单词本练一轮，卡片会出现在这里。",
}: DepthCarouselProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const tintRefs = useRef<Array<HTMLSpanElement | null>>([]);

  // 转盘的位置、缩放、补间都活在 ref 里：拖动时每帧直接改 transform。
  const posRef = useRef(0);
  const focusRef = useRef(0);
  const scaleRef = useRef(1);
  const tweenRef = useRef<gsap.core.Tween | null>(null);
  const dragRef = useRef<{
    x: number;
    startPos: number;
    lastX: number;
    lastT: number;
    speed: number;
    moved: boolean;
    pointerId: number;
  } | null>(null);
  // window.setTimeout 在浏览器里给的是数字句柄（Node 的 Timeout 不是这里的类型）。
  const wheelTimerRef = useRef<number | null>(null);
  const [active, setActive] = useState(0);
  const [flatScreen, setFlatScreen] = useState(false);

  const count = items.length;
  const flat = flatScreen;

  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;

  /**
   * 把每一张卡按当前位置摆好。这是整个组件的核心：
   * `pos` 是转盘的连续位置（2.4 表示停在 2 和 3 之间），
   * 每张卡算它离镜头有几个格子 `d`，越靠后越小、越暗、越偏。
   */
  const layout = useCallback((pos: number) => {
    const total = cardRefs.current.length;
    if (!total) return;
    const scale = scaleRef.current;

    for (let index = 0; index < total; index += 1) {
      const node = cardRefs.current[index];
      if (!node) continue;

      let d = index - pos;
      if (total > 1) {
        // 环形：最后一张的前面就是第一张，转盘转起来才是无缝的。
        d = ((d % total) + total) % total;
        if (d > total / 2) d -= total;
      }

      const back = Math.max(0, d);
      const distance = Math.abs(d);
      const shown = distance <= VISIBLE + 0.5;

      let opacity = d < 0 ? Math.max(0, 1 + d) : 1;
      if (!shown) opacity = 0;

      const blur = Math.min(BLUR, (back / Math.max(1, VISIBLE)) * BLUR);
      node.style.transform =
        `translate(-50%, -50%) scale(${scale})` +
        ` translateX(${(SPREAD * d).toFixed(2)}px)` +
        ` translateZ(${(-DEPTH * d).toFixed(2)}px)` +
        ` rotateY(${(TILT * clamp(d, 0, 1)).toFixed(3)}deg)`;
      node.style.opacity = opacity.toFixed(3);
      node.style.filter = blur > 0.01 ? `blur(${blur.toFixed(2)}px)` : "none";
      // 前面的压着后面的；正对镜头的按 Tab 能进去，别的先退出去。
      node.style.zIndex = String(Math.round(2000 - d * 20));
      node.style.pointerEvents = shown && opacity > 0.05 ? "auto" : "none";

      const tint = tintRefs.current[index];
      if (tint) {
        tint.style.opacity = clamp(back * FALLOFF * 1.25, 0, 0.5).toFixed(3);
      }
    }
  }, []);

  const notify = useCallback((index: number) => {
    setActive(index);
  }, []);

  /** 把转盘转到 `pos`；`animate` 为假就直接跳过去。 */
  const tweenTo = useCallback(
    (target: number, animate: boolean) => {
      tweenRef.current?.kill();
      const proxy = { p: posRef.current };
      tweenRef.current = gsap.to(proxy, {
        p: target,
        duration: animate ? DURATION : 0,
        ease: EASE,
        onUpdate: () => {
          posRef.current = proxy.p;
          layout(proxy.p);
        },
        onComplete: () => {
          const total = cardRefs.current.length;
          if (total > 0) posRef.current = ((posRef.current % total) + total) % total;
          layout(posRef.current);
        },
      });
    },
    [layout],
  );

  /** 转到第 `rawIndex` 张。delta 取环形里最近的那条路，转盘不会绕远。 */
  const setFocus = useCallback(
    (rawIndex: number, animate = true) => {
      const total = cardRefs.current.length;
      if (!total) return;
      const index = ((rawIndex % total) + total) % total;
      let delta = index - posRef.current;
      if (total > 1) {
        delta = ((delta % total) + total) % total;
        if (delta > total / 2) delta -= total;
      }
      tweenTo(posRef.current + delta, animate);
      if (index !== focusRef.current) {
        focusRef.current = index;
        notify(index);
      }
    },
    [tweenTo, notify],
  );

  const step = useCallback(
    (by: number) => setFocus(focusRef.current + by, true),
    [setFocus],
  );

  // 容器宽度不够时整盘缩小，卡片不会挤到画面外面去。
  useEffect(() => {
    const root = rootRef.current;
    if (!root || flat) return;
    const observer = new ResizeObserver((entries) => {
      const width = entries[0]?.contentRect.width ?? 0;
      if (width <= 0) return;
      const needed = CARD_WIDTH + SPREAD * 2 + 120;
      scaleRef.current = clamp(width / needed, 0.42, 1);
      layout(posRef.current);
    });
    observer.observe(root);
    return () => observer.disconnect();
  }, [flat, layout]);

  // 滚轮翻页：攒够一张卡的距离就翻一格，停下 130ms 后吸附到最近的格子。
  useEffect(() => {
    const root = rootRef.current;
    if (!root || flat || count < 2) return;
    const onWheel = (event: WheelEvent) => {
      event.preventDefault();
      tweenRef.current?.kill();
      const raw =
        Math.abs(event.deltaX) > Math.abs(event.deltaY)
          ? event.deltaX
          : event.deltaY;
      const delta = event.deltaMode === 1 ? raw * 24 : raw;
      posRef.current += clamp(delta / (CARD_WIDTH * 0.9), -0.6, 0.6);
      layout(posRef.current);
      if (wheelTimerRef.current) window.clearTimeout(wheelTimerRef.current);
      wheelTimerRef.current = window.setTimeout(
        () => setFocus(Math.round(posRef.current), true),
        130,
      );
    };
    root.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      root.removeEventListener("wheel", onWheel);
      if (wheelTimerRef.current) window.clearTimeout(wheelTimerRef.current);
    };
  }, [flat, count, layout, setFocus]);

  // 窄屏和「减少动态效果」都退成平铺网格。
  useEffect(() => {
    const query = window.matchMedia(
      "(prefers-reduced-motion: reduce), (max-width: 760px)",
    );
    const apply = () => setFlatScreen(query.matches);
    apply();
    query.addEventListener("change", apply);
    return () => query.removeEventListener("change", apply);
  }, []);

  // 从网格切回转盘时把卡重新摆一遍（那时 refs 才刚挂上）。
  useEffect(() => {
    if (!flat) layout(posRef.current);
  }, [flat, layout, count]);

  useEffect(
    () => () => {
      tweenRef.current?.kill();
      if (wheelTimerRef.current) window.clearTimeout(wheelTimerRef.current);
    },
    [],
  );

  const onPointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (count < 2) return;
      tweenRef.current?.kill();
      dragRef.current = {
        x: event.clientX,
        startPos: posRef.current,
        lastX: event.clientX,
        lastT: performance.now(),
        speed: 0,
        moved: false,
        pointerId: event.pointerId,
      };
    },
    [count],
  );

  const onPointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      if (!drag) return;
      // 手指在屏幕上横向划：一张卡 55% 的宽度算一格。
      const perCard = Math.max(CARD_WIDTH * 0.55 * scaleRef.current, 40);
      const dx = event.clientX - drag.x;
      if (!drag.moved && Math.abs(dx) > 4) {
        drag.moved = true;
        rootRef.current?.setPointerCapture(drag.pointerId);
      }
      if (!drag.moved) return;
      const now = performance.now();
      drag.speed = (event.clientX - drag.lastX) / Math.max(now - drag.lastT, 1);
      drag.lastX = event.clientX;
      drag.lastT = now;
      posRef.current = drag.startPos - dx / perCard;
      layout(posRef.current);
    },
    [layout],
  );

  const onPointerEnd = useCallback(() => {
    const drag = dragRef.current;
    if (!drag) return;
    dragRef.current = null;
    if (!drag.moved) return;
    // 甩出去的那一下要算数：按松手时的速度往前多滑一点。
    const perCard = Math.max(CARD_WIDTH * 0.55 * scaleRef.current, 40);
    const projected = posRef.current - (drag.speed * 180) / perCard;
    setFocus(Math.round(projected), true);
  }, [setFocus]);

  const onKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        step(-1);
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        step(1);
      } else if (event.key === "Enter" || event.key === " ") {
        // 键盘用户进不了「点一下转正、再点一下打开」那套，中间那张直接开。
        const item = items[focusRef.current];
        if (item) {
          event.preventDefault();
          onSelectRef.current?.(item);
        }
      }
    },
    [items, step],
  );

  const onCardClick = useCallback(
    (index: number) => {
      if (dragRef.current?.moved) return;
      // 先转正，再打开 —— 手滑点到后面那张的时候不会莫名其妙跳走。
      if (index !== focusRef.current) {
        setFocus(index, true);
        return;
      }
      const item = items[index];
      if (item) onSelectRef.current?.(item);
    },
    [items, setFocus],
  );

  const hues = useMemo(
    () => items.map((item) => Math.round(hash01(item.id, 7) * 360)),
    [items],
  );

  const cardBody = (item: DepthCarouselItem) =>
    item.image ? (
      // 图卡：整张面交给图（图里已经写好了标题），读屏走 aria-label。
      <img
        className="depth-carousel__cover"
        src={item.image}
        alt=""
        draggable={false}
      />
    ) : (
      <>
        <span className="depth-carousel__wash" aria-hidden="true" />
        <span className="depth-carousel__glyph" aria-hidden="true">
          {item.word.slice(0, 1).toUpperCase()}
        </span>
        <span className="depth-carousel__word">{item.word}</span>
        {item.tag ? <span className="depth-carousel__tag">{item.tag}</span> : null}
        {item.meaning ? (
          <span className="depth-carousel__meaning">{item.meaning}</span>
        ) : null}
        {typeof item.rounds === "number" ? (
          <span className="depth-carousel__rounds">
            {item.rounds > 0 ? `复习 ${item.rounds} 轮` : "待复习"}
          </span>
        ) : null}
      </>
    );

  if (!count) {
    return (
      <div className={`depth-carousel depth-carousel--empty ${className}`.trim()}>
        <p>{emptyLabel}</p>
      </div>
    );
  }

  // 平铺：不转、不缩、不糊，同样一屏看全。窄屏和「减少动态效果」走这条。
  if (flat) {
    return (
      <div
        className={`depth-carousel depth-carousel--flat ${className}`.trim()}
        role="list"
        aria-label="背过的卡片"
      >
        {items.map((item, index) => (
          <button
            key={item.id}
            type="button"
            role="listitem"
            className="depth-carousel__card"
            data-cover={item.image ? "" : undefined}
            style={{ ["--dc-hue" as string]: String(hues[index]) }}
            onClick={() => onSelectRef.current?.(item)}
            aria-label={`卡片 ${item.word}${item.meaning ? `，${item.meaning}` : ""}`}
          >
            {cardBody(item)}
          </button>
        ))}
      </div>
    );
  }

  return (
    <div
      ref={rootRef}
      className={`depth-carousel ${className}`.trim()}
      style={{ "--dc-perspective": "1400px" } as CSSProperties}
      role="group"
      aria-roledescription="carousel"
      aria-label="背过的卡片"
      tabIndex={0}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerEnd}
      onPointerCancel={onPointerEnd}
      onKeyDown={onKeyDown}
    >
      <div className="depth-carousel__stage">
        {items.map((item, index) => (
          <button
            key={item.id}
            type="button"
            ref={(node) => {
              cardRefs.current[index] = node;
            }}
            className="depth-carousel__card"
            data-cover={item.image ? "" : undefined}
            style={{
              ["--dc-hue" as string]: String(hues[index]),
              // 图卡没有文字撑着，尺寸得给死 —— 转盘本来就是按这个尺寸算的。
              ...(item.image ? { width: CARD_WIDTH, height: CARD_HEIGHT } : null),
            }}
            aria-roledescription="slide"
            aria-label={`${index + 1} / ${count}：${item.word}`}
            aria-hidden={active !== index}
            tabIndex={-1}
            onClick={() => onCardClick(index)}
          >
            {cardBody(item)}
            <span
              className="depth-carousel__veil"
              ref={(node) => {
                tintRefs.current[index] = node;
              }}
              aria-hidden="true"
            />
          </button>
        ))}
      </div>

      {count > 1 ? (
        <>
          <button
            type="button"
            className="depth-carousel__arrow depth-carousel__arrow--prev"
            aria-label="上一张"
            onClick={() => step(-1)}
          >
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
              <path
                d="M15 5l-7 7 7 7"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
          <button
            type="button"
            className="depth-carousel__arrow depth-carousel__arrow--next"
            aria-label="下一张"
            onClick={() => step(1)}
          >
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
              <path
                d="M9 5l7 7-7 7"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
          <div className="depth-carousel__dots" role="tablist" aria-label="卡片">
            {items.map((item, index) => (
              <button
                key={item.id}
                type="button"
                role="tab"
                aria-selected={active === index}
                aria-label={`第 ${index + 1} 张：${item.word}`}
                className={`depth-carousel__dot${active === index ? " is-active" : ""}`}
                onClick={() => setFocus(index, true)}
              />
            ))}
          </div>
        </>
      ) : null}

      <p className="depth-carousel__hint" aria-hidden="true">
        拖动 / 滚轮翻页 · 点中间那张打开
      </p>
    </div>
  );
}

export default DepthCarousel;
