// Cross-component handshake between the 3D room and the intro curtain.
//
// The curtain lives outside the Canvas tree, so it cannot read r3f state; a
// plain window event keeps the two decoupled and works no matter which one
// mounts first. The flag answers "already ready" questions, since the event
// itself only fires once per page load.

export const SCENE_READY_EVENT = "leafia:scene-ready";

declare global {
  interface Window {
    __leafiaSceneReady?: boolean;
  }
}

/** Called by the shelf after its first painted WebGL frame. Idempotent. */
export function markSceneReady() {
  if (typeof window === "undefined" || window.__leafiaSceneReady) return;
  window.__leafiaSceneReady = true;
  window.dispatchEvent(new Event(SCENE_READY_EVENT));
}

export function isSceneReady() {
  return typeof window !== "undefined" && window.__leafiaSceneReady === true;
}

/**
 * Runs the callback immediately when the scene is already up, otherwise on
 * the next readiness event. Returns an unsubscribe for the pending case.
 */
export function whenSceneReady(callback: () => void) {
  if (isSceneReady()) {
    callback();
    return () => {};
  }
  const handler = () => callback();
  window.addEventListener(SCENE_READY_EVENT, handler);
  return () => window.removeEventListener(SCENE_READY_EVENT, handler);
}
